82	static void boot_flash_power_on(void)
83	{
84	#define V58_PIN (58U)
85	    uint8_t pin = V58_PIN;
86	
87	#if 0
88	    //GPIO_InitTypeDef gpio_config;
89	    //GPIO_A39
90	    gpio_config.Pin = 39;
91	    gpio_config.Mode = GPIO_MODE_OUTPUT;
92	    gpio_config.Pull = GPIO_NOPULL;
93	
94	    HAL_GPIO_Init(hwp_gpio1, &gpio_config);
95	    HAL_GPIO_WritePin(hwp_gpio1, 39, GPIO_PIN_SET);
96	#endif
97	
98	    /* enable V43 */
99	    pin = 43 - 32;
100	    (hwp_gpio1 + 1)->DOESR |= (1UL << pin);
101	    (hwp_gpio1 + 1)->DOR |= (1UL << pin);
102	
103	    /* enable V33 */
104	    pin = 33 - 32;
105	    (hwp_gpio1 + 1)->DOESR |= (1UL << pin);
106	    (hwp_gpio1 + 1)->DOR |= (1UL << pin);
107	
108	    /* enable V26 */
109	    pin = 26;
110	    (hwp_gpio1 + 0)->DOESR |= (1UL << pin);
111	    (hwp_gpio1 + 0)->DOR |= (1UL << pin);
112	
113	#ifdef SOC_BF0_HCPU
114	    // Enable PADA
115	    HAL_HPAON_ENABLE_PAD();
116	
117	    HAL_PBR0_FORCE1_ENABLE();
118	    HAL_PBR_ConfigMode(0, 1); //set PBR0 output
119	    HAL_PBR_WritePin(0, 1); //set PBR0 high
120	
121	#endif /* SOC_BF0_HCPU */
122	
123	    dwtIpInit();
124	    /* wait until 2ms elapse to ensure flash LDO is stable before flash access
125	     * default clock is 24MHz, maybe slower than 24MHz at startup stage
126	     *
127	     */
128	    while (dwtGetCycles() < (2 * 24000))
129	    {
130	    }
131	
132	    dwtIpDeinit();
133	
134	#if defined(SOC_SF32LB58X) && defined(FPGA)
135	    HAL_QSPI_SET_RXDELAY(0, 0, 2);
136	    HAL_QSPI_SET_RXDELAY(1, 0, 2);
137	#endif
138	}
