533	/****************************************************************************
534	 * Name: BSP_Board_PreInit
535	 *
536	 * Description:
537	 *   Board pre-init for nxboot bootloader.
538	 *   Configures clocks (XT48, DLL1/2/3), flash clocks, and PSRAM clocks.
539	 *   Based on the main board's bsp_init.c but simplified for bootloader use.
540	 *
541	 ****************************************************************************/
542	
543	void BSP_Board_PreInit(void)
544	{
545	  /* Enable XT48 oscillator */
546	  HAL_HPAON_EnableXT48();
547	
548	  /* Select system clock to HXT48 (48 MHz) */
549	  HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_SYS, RCC_SYSCLK_HXT48);
550	  HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_HP_PERI, RCC_CLK_PERI_HXT48);
551	
552	  if (PM_STANDBY_BOOT != SystemPowerOnModeGet())
553	    {
554	      /* Halt LCPU first to avoid LCPU in running state */
555	      HAL_HPAON_WakeCore(CORE_ID_LCPU);
556	      HAL_RCC_Reset_and_Halt_LCPU(1);
557	
558	      /* Enable DLL1 at 240 MHz for system clock */
559	      HAL_PMU_EnableDLL(1);
560	      HAL_PMU_SWITCH_VRET_LOWER();
561	      HAL_HPAON_StartGTimer();
562	
563	      /* Configure LCPU clocks */
564	      HAL_RCC_LCPU_ClockSelect(RCC_CLK_MOD_LP_PERI, RCC_CLK_PERI_HXT48);
565	      HAL_LPAON_EnableXT48();
566	      HAL_RCC_LCPU_ClockSelect(RCC_CLK_MOD_SYS, RCC_SYSCLK_HXT48);
567	      HAL_RCC_LCPU_SetDiv(1, 1, 3);
568	    }
569	
570	  __HAL_SYSCFG_HPBG_EN();
571	  __HAL_SYSCFG_HPBG_VDDPSW_EN();
572	
573	  /* Enable DLL1 at 240 MHz and select as system clock */
574	  HAL_RCC_HCPU_EnableDLL1(240000000);
575	  HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_SYS, RCC_SYSCLK_DLL1);
576	
577	  /* Reset sysclk used by HAL_Delay_us */
578	  HAL_Delay_us(0);
579	
580	  /* Set flash dividers */
581	  mpi1_div = 1;
582	  mpi2_div = 1;
583	  mpi3_div = 3;
584	  mpi4_div = 3;
585	  mpi5_div = 1;
586	
587	  /* Read OTP calibration data (PMU, SIP mode, crystal, etc.) */
588	  *(volatile uint32_t *)0x20001F30 = 0xAAAAAAAA;  /* before BSP_System_Config */
589	  BSP_System_Config();
590	  *(volatile uint32_t *)0x20001F30 = 0xBBBBBBBB;  /* after BSP_System_Config */
591	
592	  /* Init the low level hardware (pinmux, power) */
593	  HAL_MspInit();
594	
595	  if (mpi3_div <= 4)
596	    {
597	      HAL_QSPI_SET_RXDELAY(2, 1, 0);
598	    }
599	
600	  /* Enable DLL2 (288 MHz) for PSRAM, DLL3 (216 MHz) for flash */
601	  HAL_RCC_HCPU_EnableDLL2(288000000);
602	  HAL_RCC_HCPU_EnableDLL3(216000000);
603	  HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_FLASH3, RCC_CLK_FLASH_DLL3);
604	  HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_FLASH4, RCC_CLK_FLASH_DLL3);
605	
606	#ifdef BSP_USING_PSRAM
607	  HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_FLASH1, RCC_CLK_FLASH_DLL2);
608	  HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_FLASH2, RCC_CLK_FLASH_DLL2);
609	#endif
610	
611	  /* Set system clock dividers */
612	  HAL_RCC_HCPU_SetDiv(1, 2, 5);
613	  HAL_RCC_HCPU_DeepWFIClockSelect(true, RCC_SYSCLK_HXT48);
614	  HAL_RCC_HCPU_SetDeepWFIDiv(48, 0, 1);
615	}
