57	      return false;
58	    }
59	
60	  if (flash_partition_read(fd, &flag, 1,
61	                           info.size - info.blocksize * (index + 1)) < 0)
62	    {
63	      return false;
64	    }
65	
66	  return flag == 0xfe;
67	}
68	
69	static inline int set_image_flag(int fd, int index)
70	{
71	  uint8_t flag;
72	  struct flash_partition_info info;
73	
74	  if (flash_partition_info(fd, &info) < 0)
75	    {
76	      return ERROR;
77	    }
78	
79	  flag = 0xfe;
80	  return flash_partition_write(fd, &flag, 1,
81	                               info.size - (info.blocksize * (index + 1)));
82	}
83	
84	static inline void get_image_header(int fd, struct nxboot_img_header *header)
85	{
86	  int ret;
87	  ret = flash_partition_read(fd, header, sizeof *header, 0);
88	  if (ret < 0)
89	    {
90	      /* Something went wrong, treat the partition as empty. */
91	
92	      memset(header, 0, sizeof *header);
93	    }
94	}
95	
96	static inline bool validate_image_header(struct nxboot_img_header *header)
97	{
98	  return header->magic == NXBOOT_HEADER_MAGIC ||
99	         header->magic == NXBOOT_HEADER_MAGIC_INV;
100	}
101	
102	static uint32_t calculate_crc(int fd, struct nxboot_img_header *header)
103	{
104	  char *buf;
105	  int remain;
106	  int readsiz;
107	  off_t off;
108	  uint32_t crc;
109	  struct flash_partition_info info;
110	
111	  if (flash_partition_info(fd, &info) < 0)
112	    {
113	      return false;
114	    }
115	
116	  buf = malloc(info.blocksize);
117	  if (!buf)
118	    {
119	      return false;
120	    }
121	
122	  crc = 0xffffffff;
123	  remain = header->size;
124	  off = CONFIG_NXBOOT_HEADER_SIZE;
125	  while (remain > 0)
126	    {
127	      readsiz = remain > info.blocksize ? info.blocksize : remain;
128	      if (flash_partition_read(fd, buf, readsiz, off) != 0)
129	        {
130	          free(buf);
131	          return 0xffffffff;
132	        }
133	
134	      off += readsiz;
135	      remain -= readsiz;
136	      crc = crc32part((uint8_t *)buf, readsiz, crc);
137	    }
138	
139	  free(buf);
140	  return ~crc;
141	}
142	
143	static int copy_partition(int from, int where)
144	{
145	  struct nxboot_img_header header;
146	  struct flash_partition_info info_from;
147	  struct flash_partition_info info_where;
148	  uint32_t crc;
149	  uint32_t magic;
150	  int readsiz;
151	  int remain;
152	  int blocksize;
153	  off_t off;
154	  char *buf;
155	
156	  get_image_header(from, &header);
157	
158	  if (flash_partition_info(from, &info_from) < 0)
159	    {
160	      return ERROR;
161	    }
162	
163	  if (flash_partition_info(where, &info_where) < 0)
164	    {
165	      return ERROR;
166	    }
167	
168	  if ((header.size + CONFIG_NXBOOT_HEADER_SIZE) > info_where.size)
169	    {
170	      return ERROR;
171	    }
172	
173	  blocksize = MAX(info_from.blocksize, info_where.blocksize);
174	
175	  buf = malloc(blocksize);
176	  if (!buf)
177	    {
178	      return ERROR;
179	    }
180	
181	  if (flash_partition_erase_last_sector(where) < 0)
182	    {
183	      return ERROR;
184	    }
185	
186	  remain = header.size + CONFIG_NXBOOT_HEADER_SIZE;
187	  off = 0;
188	  if (header.magic == NXBOOT_HEADER_MAGIC_INV)
189	    {
190	      /* This means we are doing a recovery of a primary image
191	       * without the precalculated CRC. Calculate CRC and insert it
192	       * into the recovery image header. Also flip header's magic to
193	       * indicate this is an image with valid CRC.
194	       */
195	
196	      magic = NXBOOT_HEADER_MAGIC;
197	      crc = calculate_crc(from, &header);
198	      if (flash_partition_read(from, buf, blocksize, 0) < 0)
199	        {
200	          free(buf);
201	          return ERROR;
202	        }
203	
204	      memcpy(buf + offsetof(struct nxboot_img_header, magic), &magic,
205	             sizeof magic);
206	      memcpy(buf + offsetof(struct nxboot_img_header, crc), &crc,
207	             sizeof crc);
208	      if (flash_partition_write(where, buf, blocksize, 0) < 0)
209	        {
210	          free(buf);
211	          return ERROR;
212	        }
213	
214	      off += blocksize;
215	      remain -= blocksize;
216	    }
217	
218	  while (remain > 0)
219	    {
220	      readsiz = remain > blocksize ? blocksize : remain;
221	      if (flash_partition_read(from, buf, readsiz, off) < 0)
222	        {
223	          free(buf);
224	          return ERROR;
225	        }
226	
227	      if (flash_partition_write(where, buf, readsiz, off) < 0)
228	        {
229	          free(buf);
230	          return ERROR;
231	        }
232	
233	      off += readsiz;
234	      remain -= readsiz;
235	    }
236	
237	  if (header.magic != NXBOOT_HEADER_MAGIC_INV)
238	    {
239	      /* Copy currently set flags but only if the image has
240	       * precalculated CRC.
241	       */
242	
243	      if (get_image_flag(from, NXBOOT_UPDATED_PAGE_INDEX))
244	        {
245	          set_image_flag(where, NXBOOT_UPDATED_PAGE_INDEX);
246	        }
247	
248	      if (get_image_flag(from, NXBOOT_CONFIRMED_PAGE_INDEX))
249	        {
250	          set_image_flag(where, NXBOOT_CONFIRMED_PAGE_INDEX);
251	        }
252	    }
253	  else
254	    {
255	      set_image_flag(where, NXBOOT_CONFIRMED_PAGE_INDEX);
256	    }
257	
258	  free(buf);
259	  return OK;
260	}
261	
262	static bool validate_image(int fd)
263	{
264	  struct nxboot_img_header header;
265	
266	  get_image_header(fd, &header);
267	  if (!validate_image_header(&header))
268	    {
269	      return false;
270	    }
271	
272	  if (header.magic == NXBOOT_HEADER_MAGIC_INV)
273	    {
274	      /* Images with no precalculated CRC are considered valid. These
275	       * should be the images that are uploaded directly to the primary
276	       * paritition with debugger/flasher and are not uploaded by the
277	       * bootloader. These images also don't have confirmed flags,
278	       * altough they are considered stable.
279	       */
280	
281	      return true;
282	    }
283	  else
284	    {
285	      return calculate_crc(fd, &header) == header.crc;
286	    }
287	}
288	
289	static bool compare_versions(struct nxboot_img_version *v1,
290	                             struct nxboot_img_version *v2)
291	{
292	#ifndef CONFIG_NXBOOT_PREVENT_DOWNGRADE
293	  int i;
294	  if (v1->major != v2->major ||
295	      v1->minor != v2->minor ||
296	      v1->patch != v2->patch)
297	    {
298	      return false;
299	    }
300	
301	  for (i = 0; i < NXBOOT_HEADER_PRERELEASE_MAXLEN; i++)
302	    {
303	      if (v1->pre_release[i] != v2->pre_release[i])
304	        {
305	          return false;
306	        }
307	    }
308	
309	  return true;
310	#else
311	  if (v1->major > v2->major ||
312	      v1->minor > v2->minor ||
313	      v1->patch > v2->patch)
314	    {
315	      return true;
316	    }
317	
318	  if (v1->major == v2->major &&
319	      v1->minor == v2->minor &&
320	      v1->patch == v2->patch)
321	    {
322	      /* TODO: compare prerelease */
323	    }
324	
325	  return false;
326	#endif
327	}
328	
329	static enum nxboot_update_type
330	  get_update_type(int primary, int update, int recovery,
331	                  struct nxboot_img_header *primary_header,
332	                  struct nxboot_img_header *update_header)
333	{
334	  if (get_image_flag(recovery, NXBOOT_CONFIRMED_PAGE_INDEX) &&
335	      get_image_flag(update, NXBOOT_UPDATED_PAGE_INDEX) &&
336	      ((!get_image_flag(primary, NXBOOT_CONFIRMED_PAGE_INDEX) &&
337	      primary_header->magic != NXBOOT_HEADER_MAGIC_INV) ||
338	      !validate_image(primary)) && validate_image(recovery))
339	    {
340	      return NXBOOT_UPDATE_TYPE_REVERT;
341	    }
342	
343	  if (!get_image_flag(update, NXBOOT_CONFIRMED_PAGE_INDEX) &&
344	      !get_image_flag(update, NXBOOT_UPDATED_PAGE_INDEX) &&
345	      validate_image(update))
346	    {
347	      if (compare_versions(&primary_header->img_version,
348	                           &update_header->img_version) &&
349	          validate_image(primary))
350	        {
351	          return NXBOOT_UPDATE_TYPE_NONE;
352	        }
353	
354	      return NXBOOT_UPDATE_TYPE_UPDATE;
355	    }
356	
357	  return NXBOOT_UPDATE_TYPE_NONE;
358	}
359	
360	static int perform_update(struct nxboot_state *state, bool check_only)
361	{
362	  int update;
363	  int recovery;
364	  int primary;
365	  int secondary;
366	  int tertiary;
367	  bool primary_valid;
368	
369	  syslog(LOG_INFO, "perform_update: opening primary\n");
370	  primary = flash_partition_open(CONFIG_NXBOOT_PRIMARY_SLOT_PATH);
371	  syslog(LOG_INFO, "perform_update: primary fd=%d\n", primary);
372	  assert(primary >= 0);
373	
374	  syslog(LOG_INFO, "perform_update: opening secondary\n");
375	  secondary = flash_partition_open(CONFIG_NXBOOT_SECONDARY_SLOT_PATH);
376	  syslog(LOG_INFO, "perform_update: secondary fd=%d\n", secondary);
377	  assert(secondary >= 0);
378	
379	  tertiary = flash_partition_open(CONFIG_NXBOOT_TERTIARY_SLOT_PATH);
380	  assert(tertiary >= 0);
381	
382	  if (state->update == NXBOOT_SECONDARY_SLOT_NUM)
383	    {
384	      update = secondary;
385	      recovery = tertiary;
386	    }
387	  else
388	    {
389	      update = tertiary;
390	      recovery = secondary;
391	    }
392	
393	  if (state->next_boot == NXBOOT_UPDATE_TYPE_REVERT &&
394	      (!check_only || !validate_image(primary)))
395	    {
396	      if (validate_image(recovery))
397	        {
398	          syslog(LOG_INFO, "Reverting image to recovery.\n");
399	          copy_partition(recovery, primary);
400	        }
401	    }
402	  else
403	    {
404	      primary_valid = validate_image(primary);
405	      if (primary_valid && check_only)
406	        {
407	          /* Skip if primary image is valid (does not mather whether
408	           * confirmed or not) and check_only option is set.
409	           */
410	
411	          goto perform_update_done;
412	        }
413	
414	      if (!state->recovery_valid && state->primary_confirmed &&
415	          primary_valid)
416	        {
417	          /* Save current image as recovery only if it is valid and
418	           * confirmed. We have to check this in case of restart
419	           * during update process.
420	           * If board is restarted during update, primary slot contains
421	           * non-valid image and we do not want to copy this image to
422	           * recovery slot.
423	           * There also might be a case where primary image is valid
424	           * but not confirmed (timing of board reset right after
425	           * update is uploaded to secondary). Still we do not want
426	           * to upload this to recovery.
427	           */
428	
429	          syslog(LOG_INFO, "Creating recovery image.\n");
430	          copy_partition(primary, recovery);
431	          if (!validate_image(recovery))
432	            {
433	              syslog(LOG_INFO, "New recovery is not valid, stop update\n");
434	              goto perform_update_done;
435	            }
436	
437	          syslog(LOG_INFO, "Recovery image created.\n");
438	        }
439	
440	      if (validate_image(update))
441	        {
442	          /* Perform update only if update slot contains valid image. */
443	
444	          syslog(LOG_INFO, "Updating from update image.\n");
445	          copy_partition(update, primary);
446	
447	          /* Mark update slot as updated. This is to prevent repeated
448	           * updates.
449	           */
450	
451	          set_image_flag(update, NXBOOT_UPDATED_PAGE_INDEX);
452	        }
453	    }
454	
455	perform_update_done:
456	  flash_partition_close(primary);
457	  flash_partition_close(secondary);
458	  flash_partition_close(tertiary);
459	  return OK;
460	}
