98	/****************************************************************************
99	 * Name: flash_partition_write
100	 *
101	 * Description:
102	 *   Writes count data pointed to by buf at offset off to a partition
103	 *   referenced by file descriptor fd.
104	 *
105	 * Input parameters:
106	 *   fd: Valid file descriptor.
107	 *   buf: The pointer to data to be written.
108	 *   count: Number of bytes to be written.
109	 *   off: Write offset in bytes.
110	 *
111	 * Returned Value:
112	 *   0 on success, -1 on failure.
113	 *
114	 ****************************************************************************/
115	
116	int flash_partition_write(int fd, const void *buf, size_t count, off_t off)
117	{
118	  int ret;
119	  off_t pos;
120	  size_t size;
121	  ssize_t nbytes;
122	  struct mtd_geometry_s geometry;
123	
124	  ret = ioctl(fd, MTDIOC_GEOMETRY, (unsigned long)((uintptr_t)&geometry));
125	  if (ret < 0)
126	    {
127	      syslog(LOG_ERR, "ioctl MTDIOC_GEOMETRY failed: %s\n", strerror(errno));
128	      return ERROR;
129	    }
130	
131	  size = geometry.erasesize * geometry.neraseblocks;
132	  if (count + off > size)
133	    {
134	      syslog(LOG_ERR, "Trying to write outside of flash area.\n");
135	      return ERROR;
136	    }
137	
138	  pos = lseek(fd, off, SEEK_SET);
139	  if (pos != off)
140	    {
141	      syslog(LOG_ERR, "Could not seek to %ld: %s\n", off, strerror(errno));
142	      return ERROR;
143	    }
144	
145	  nbytes = write(fd, buf, count);
146	  if (nbytes != count)
147	    {
148	      syslog(LOG_ERR, "Write to offset %ld failed %s\n",
149	              off, strerror(errno));
150	      return ERROR;
151	    }
152	
153	  return OK;
154	}
