156	/****************************************************************************
157	 * Name: flash_partition_read
158	 *
159	 * Description:
160	 *   Read count data to buffer buf at offset off from a partition
161	 *   referenced by file descriptor fd.
162	 *
163	 * Input parameters:
164	 *   fd: Valid file descriptor.
165	 *   buf: The pointer where read data are stored.
166	 *   count: Number of bytes to be read.
167	 *   off: Read offset in bytes.
168	 *
169	 * Returned Value:
170	 *   0 on success, -1 on failure.
171	 *
172	 ****************************************************************************/
173	
174	int flash_partition_read(int fd, void *buf, size_t count, off_t off)
175	{
176	  int ret;
177	  off_t pos;
178	  size_t size;
179	  ssize_t nbytes;
180	  struct mtd_geometry_s geometry;
181	
182	  syslog(LOG_INFO, "flash_partition_read: fd=%d count=%lu off=%ld\n",
183	         fd, (unsigned long)count, (long)off);
184	  ret = ioctl(fd, MTDIOC_GEOMETRY, (unsigned long)((uintptr_t)&geometry));
185	  syslog(LOG_INFO, "flash_partition_read: ioctl ret=%d\n", ret);
186	  if (ret < 0)
187	    {
188	      syslog(LOG_ERR, "ioctl MTDIOC_GEOMETRY failed: %s\n", strerror(errno));
189	      return ERROR;
190	    }
191	
192	  size = geometry.erasesize * geometry.neraseblocks;
193	  if (count + off > size)
194	    {
195	      syslog(LOG_ERR, "Trying to read outside of flash area.\n");
196	      return ERROR;
197	    }
198	
199	  pos = lseek(fd, off, SEEK_SET);
200	  syslog(LOG_INFO, "flash_partition_read: lseek pos=%ld\n", (long)pos);
201	  if (pos != off)
202	    {
203	      syslog(LOG_ERR, "Could not seek to %ld: %s\n", off, strerror(errno));
204	      return ERROR;
205	    }
206	
207	  syslog(LOG_INFO, "flash_partition_read: calling read(%d, %p, %lu)\n",
208	         fd, buf, (unsigned long)count);
209	  nbytes = read(fd, buf, count);
210	  syslog(LOG_INFO, "flash_partition_read: read returned %ld\n", (long)nbytes);
211	  if (nbytes != count)
212	    {
213	      syslog(LOG_ERR, "Read from offset %ld failed %s\n",
214	              off, strerror(errno));
215	      return ERROR;
216	    }
217	
218	  return OK;
219	}
