177	 *   Layout (each field is uint32_t):
178	 *     [0]  = 0x4E584254  ("NXBT" magic)
179	 *     [1]  = partition size (all same)
180	 *     [2]  = open result bitmask (bit0=primary, bit1=secondary, bit2=tertiary)
181	 *     [3]  = primary magic
182	 *     [4]  = primary image size
183	 *     [5]  = primary image CRC
184	 *     [6]  = primary version: (major << 16) | minor
185	 *     [7]  = primary patch
186	 *     [8]  = secondary magic
187	 *     [9]  = secondary image size
188	 *     [10] = secondary image CRC
189	 *     [11] = secondary version
190	 *     [12] = secondary patch
191	 *     [13] = tertiary magic
192	 *     [14] = tertiary image size
193	 *     [15] = tertiary image CRC
194	 *     [16] = tertiary version
195	 *     [17] = tertiary patch
196	 ****************************************************************************/
197	
198	static void dump_nxboot_info(void)
199	{
200	  volatile uint32_t *dbg = (volatile uint32_t *)0x20001D00;
201	  struct nxboot_img_header hdr;
202	  int fd;
203	  int i;
204	  static const char *const paths[3] =
205	  {
206	    CONFIG_NXBOOT_PRIMARY_SLOT_PATH,
207	    CONFIG_NXBOOT_SECONDARY_SLOT_PATH,
208	    CONFIG_NXBOOT_TERTIARY_SLOT_PATH
209	  };
210	
211	  /* Clear debug area */
212	  for (i = 0; i < 20; i++)
213	    {
214	      dbg[i] = 0;
215	    }
216	
217	  dbg[0] = 0x4E584254;  /* "NXBT" magic */
218	  dbg[1] = 0x00800000;  /* 8 MB per partition */
219	
220	  /* Read image headers from each partition */
221	  for (i = 0; i < 3; i++)
222	    {
223	      fd = open(paths[i], O_RDONLY);
224	      if (fd < 0)
225	        {
226	          dbg[2] |= (1u << i);
227	          continue;
228	        }
229	
230	      if (read(fd, &hdr, sizeof(hdr)) == sizeof(hdr))
231	        {
232	          dbg[3 + i * 5] = hdr.magic;
233	          dbg[4 + i * 5] = hdr.size;
234	          dbg[5 + i * 5] = hdr.crc;
235	          dbg[6 + i * 5] = ((uint32_t)hdr.img_version.major << 16) |
236	                            (uint32_t)hdr.img_version.minor;
237	          dbg[7 + i * 5] = (uint32_t)hdr.img_version.patch;
238	        }
239	
240	      close(fd);
241	    }
242	}
243	#endif
