32	/****************************************************************************
33	 * Pre-processor Definitions
34	 ****************************************************************************/
35	
36	/* Application load address in PSRAM.
37	 * Must match the application's linker script origin.
38	 * PSRAM starts at 0x60000000; first 4MB reserved for SDK regions;
39	 * application code goes at 0x60400000.
40	 */
41	
42	#define SF32LB58_APP_PSRAM_LOAD_ADDR  0x60400000
43	
44	/* Handoff flag address in retention RAM.
45	 * Written by bootloader before jumping to application.
46	 * Application checks this to know PSRAM is already initialized
47	 * and must NOT be re-initialized (would destroy the image).
48	 */
49	
50	#define SF32LB58_HANDOFF_FLAG_ADDR    0x20001FF0
51	#define SF32LB58_HANDOFF_MAGIC        0x5053524d  /* "PSRM" */
52	
53	/* Maximum image size we can load (12 MB, leaving room for heap) */
54	
55	#define SF32LB58_APP_MAX_IMAGE_SIZE   (12U * 1024U * 1024U)
56	
57	/* Read buffer size for NAND→PSRAM copy */
58	
59	#define SF32LB58_COPY_BUF_SIZE        4096
60	
61	/****************************************************************************
62	 * Private Types
63	 ****************************************************************************/
64	
65	/* ARM vector table: first two words of a Cortex-M image */
66	
67	struct arm_vector_table
68	{
69	  uint32_t spr;   /* Stack pointer on reset */
70	  uint32_t reset; /* Pointer to reset exception handler */
71	};
72	
73	/****************************************************************************
74	 * Private Functions
75	 ****************************************************************************/
76	
77	/****************************************************************************
78	 * Name: test_psram
79	 *
80	 * Description:
81	 *   Quick read/write test of PSRAM at the application load address.
82	 *   Returns OK on success, -EIO on failure.
83	 ****************************************************************************/
84	
85	static int test_psram(void)
86	{
87	  volatile uint32_t *psram = (volatile uint32_t *)SF32LB58_APP_PSRAM_LOAD_ADDR;
88	  const uint32_t pattern = 0xdeadbeef;
89	  uint32_t saved;
90	  int i;
91	
92	  /* Save original content */
93	
94	  saved = psram[0];
95	
96	  /* Write pattern to first few words */
97	
98	  for (i = 0; i < 4; i++)
99	    {
100	      psram[i] = pattern + i;
101	    }
102	
103	  /* Read back and verify */
104	
105	  for (i = 0; i < 4; i++)
106	    {
107	      if (psram[i] != pattern + i)
108	        {
109	          syslog(LOG_ERR,
110	                 "PSRAM test FAILED: [%d] wrote 0x%08lx read 0x%08lx\n",
111	                 i, (unsigned long)(pattern + i), (unsigned long)psram[i]);
112	
113	          /* Restore original */
114	
115	          psram[0] = saved;
116	          return -EIO;
117	        }
118	    }
119	
120	  /* Restore original content */
121	
122	  psram[0] = saved;
123	
124	  syslog(LOG_INFO, "PSRAM test PASSED at 0x%08lx\n",
125	         (unsigned long)SF32LB58_APP_PSRAM_LOAD_ADDR);
126	  return OK;
127	}
