170	/****************************************************************************
171	 * Public Functions
172	 ****************************************************************************/
173	
174	/****************************************************************************
175	 * Name: board_boot_image
176	 *
177	 * Description:
178	 *   Called by nxboot (via BOARDIOC_BOOT_IMAGE) to load the application
179	 *   image from NAND flash into PSRAM and jump to it.
180	 *
181	 *   IMPORTANT: PSRAM is NOT re-initialized here.  The PSRAM controller
182	 *   was set up during early boot (HAL_PreInit → bsp_psramc_init).
183	 *   Re-initializing PSRAM would destroy the application code and data
184	 *   that we copy from NAND.
185	 *
186	 * Input Parameters:
187	 *   path     - Path to the NAND MTD partition (e.g. "/dev/ota0")
188	 *   hdr_size - Size of the nxboot image header (CONFIG_NXBOOT_HEADER_SIZE)
189	 *
190	 ****************************************************************************/
191	
192	int board_boot_image(const char *path, uint32_t hdr_size)
193	{
194	  static struct arm_vector_table vt;
195	  struct file file;
196	  ssize_t bytes;
197	  uint32_t image_size;
198	  uint32_t remaining;
199	  uint32_t chunk;
200	  uint32_t dest;
201	  off_t src_off;
202	  int ret;
203	  uint8_t buf[SF32LB58_COPY_BUF_SIZE];
204	
205	  syslog(LOG_INFO, "board_boot_image: loading %s (hdr_size=0x%lx)\n",
206	         path, (unsigned long)hdr_size);
207	
208	  ret = file_open(&file, path, O_RDONLY | O_CLOEXEC);
209	  if (ret < 0)
210	    {
211	      syslog(LOG_ERR, "Failed to open %s: %d\n", path, ret);
212	      return ret;
213	    }
214	
215	  /* Read the image size from the header (offset 4, uint32_t) */
216	
217	  bytes = file_pread(&file, &image_size, sizeof(image_size), 4);
218	  if (bytes != sizeof(image_size))
219	    {
220	      syslog(LOG_ERR, "Failed to read image size: %ld\n", (long)bytes);
221	      file_close(&file);
222	      return bytes < 0 ? (int)bytes : -1;
223	    }
224	
225	  if (image_size == 0 || image_size > SF32LB58_APP_MAX_IMAGE_SIZE)
226	    {
227	      syslog(LOG_ERR, "Invalid image size: 0x%08lx\n",
228	             (unsigned long)image_size);
229	      file_close(&file);
230	      return -EINVAL;
231	    }
232	
233	  syslog(LOG_INFO, "board_boot_image: image_size=0x%08lx, copying to "
234	         "PSRAM @ 0x%08lx\n",
235	         (unsigned long)image_size,
236	         (unsigned long)SF32LB58_APP_PSRAM_LOAD_ADDR);
237	
238	  /* Verify PSRAM is accessible before copying */
239	
240	  ret = test_psram();
241	  if (ret < 0)
242	    {
243	      syslog(LOG_ERR, "PSRAM not ready, aborting boot\n");
244	      file_close(&file);
245	      return ret;
246	    }
247	
248	  /* Read the ARM vector table (SP + reset handler) from after the header */
249	
250	  bytes = file_pread(&file, &vt, sizeof(vt), hdr_size);
251	  if (bytes != sizeof(vt))
252	    {
253	      syslog(LOG_ERR, "Failed to read vector table: %ld\n", (long)bytes);
254	      file_close(&file);
255	      return bytes < 0 ? (int)bytes : -1;
256	    }
257	
258	  syslog(LOG_INFO, "board_boot_image: VT sp=0x%08lx reset=0x%08lx\n",
259	         (unsigned long)vt.spr, (unsigned long)vt.reset);
260	
261	  /* Copy the entire image from NAND to PSRAM.
262	   * We read from the NAND partition starting at hdr_size (after header)
263	   * and write to PSRAM at the load address.
264	   *
265	   * The SiFli PSRAM controller's write buffer may silently drop writes
266	   * that go through the D-cache. To work around this, we temporarily
267	   * reconfigure the PSRAM MPU region as Non-Cacheable for the copy,
268	   * then restore it afterward. This forces all writes to bypass the
269	   * D-cache and go directly to the PSRAM controller.
270	   */
271	
272	  /* Disable D-cache for the NAND→PSRAM copy.
273	   * The SiFli PSRAM controller (MPI1) has a write buffer that
274	   * may silently drop D-cache writeback writes. By disabling
275	   * the D-cache, all writes go directly to the PSRAM controller
276	   * without buffering in the cache hierarchy.
277	   */
278	
279	#ifdef CONFIG_ARMV8M_DCACHE
280	  up_disable_dcache();
281	  syslog(LOG_INFO,
282	         "board_boot_image: D-cache disabled for PSRAM copy\n");
283	#endif
284	
285	  src_off = (off_t)hdr_size;
286	  dest = SF32LB58_APP_PSRAM_LOAD_ADDR;
287	  remaining = image_size;
288	
289	  syslog(LOG_INFO, "board_boot_image: starting copy loop\n");
290	
291	  while (remaining > 0)
292	    {
293	      chunk = remaining > SF32LB58_COPY_BUF_SIZE ?
294	              SF32LB58_COPY_BUF_SIZE : remaining;
295	
296	      syslog(LOG_INFO, "  pread off=0x%08lx chunk=%lu\n",
297	             (unsigned long)src_off, (unsigned long)chunk);
298	
299	      bytes = file_pread(&file, buf, chunk, src_off);
300	      if (bytes != (ssize_t)chunk)
301	        {
302	          syslog(LOG_ERR,
303	                 "Failed to read image at offset 0x%08lx: %ld\n",
304	                 (unsigned long)src_off, (long)bytes);
305	          file_close(&file);
306	          return bytes < 0 ? (int)bytes : -1;
307	        }
308	
309	      syslog(LOG_INFO, "  memcpy dest=0x%08lx\n", (unsigned long)dest);
310	      memcpy((void *)(uintptr_t)dest, buf, chunk);
311	
312	      /* Verify the first 8 bytes of this chunk after memcpy */
313	
314	      {
315	        volatile uint32_t *verify = (volatile uint32_t *)(uintptr_t)dest;
316	        volatile uint32_t *buf32 = (volatile uint32_t *)buf;
317	        if (verify[0] != buf32[0] || verify[1] != buf32[1])
318	          {
319	            syslog(LOG_ERR,
320	                   "  MISMATCH at dest=0x%08lx: "
321	                   "PSRAM=%08lx %08lx, expected=%08lx %08lx\n",
322	                   (unsigned long)dest,
323	                   (unsigned long)verify[0], (unsigned long)verify[1],
324	                   (unsigned long)buf32[0], (unsigned long)buf32[1]);
325	          }
326	      }
327	
328	      /* Flush entire D-cache to push this chunk to PSRAM.
329	       * Range-based clean doesn't work reliably for PSRAM region.
330	       */
331	
332	#ifdef CONFIG_ARMV8M_DCACHE
333	      up_clean_dcache_all();
334	#endif
335	
336	      src_off += chunk;
337	      dest += chunk;
338	      remaining -= chunk;
339	
340	      syslog(LOG_INFO, "  chunk done, remaining=%lu\n",
341	             (unsigned long)remaining);
342	    }
343	
344	  syslog(LOG_INFO, "board_boot_image: copy loop complete\n");
345	
346	  file_close(&file);
347	
348	  syslog(LOG_INFO, "board_boot_image: file closed\n");
349	
350	  /* Verify the copy by reading back from PSRAM (D-cache is disabled,
351	   * so reads go directly to PSRAM controller).
352	   */
353	
354	  {
355	    volatile uint32_t *psram = (volatile uint32_t *)
356	                               SF32LB58_APP_PSRAM_LOAD_ADDR;
357	    syslog(LOG_INFO,
358	           "board_boot_image: PSRAM verify: %08lx %08lx %08lx %08lx\n",
359	           (unsigned long)psram[0], (unsigned long)psram[1],
360	           (unsigned long)psram[2], (unsigned long)psram[3]);
361	  }
362	
363	  /* Verify the code at the reset handler address is valid */
364	
365	  {
366	    volatile uint16_t *reset_code = (volatile uint16_t *)
367	                                    (vt.reset & ~1u);
368	    syslog(LOG_INFO,
369	           "board_boot_image: reset handler at 0x%08lx, "
370	           "code: %04x %04x %04x %04x\n",
371	           (unsigned long)vt.reset,
372	           (unsigned)reset_code[0], (unsigned)reset_code[1],
373	           (unsigned)reset_code[2], (unsigned)reset_code[3]);
374	  }
375	
376	  syslog(LOG_INFO,
377	         "board_boot_image: copy complete, jumping to PSRAM...\n");
378	
379	  /* PSRAM was initialized by HAL_PreInit() → bsp_psramc_init() early in
380	   * boot.  The application image is now loaded at SF32LB58_APP_PSRAM_LOAD_ADDR.
381	   * Do NOT re-initialize the PSRAM controller here — it would destroy the
382	   * image we just copied.
383	   *
384	   * Write a handoff flag to retention RAM so the application knows PSRAM
385	   * is already initialized and must NOT call bsp_psramc_init() again.
386	   */
387	
388	  *(volatile uint32_t *)SF32LB58_HANDOFF_FLAG_ADDR = SF32LB58_HANDOFF_MAGIC;
389	  UP_DSB();
390	
391	  systick_disable();
392	  cleanup_arm_nvic();
393	
394	  /* D-cache is already disabled (we disabled it before the copy).
395	   * Invalidate I-cache so the CPU fetches fresh code from PSRAM.
396	   * Disable MPU for the jump to avoid any memory access issues.
397	   */
398	
399	#ifdef CONFIG_ARMV8M_ICACHE
400	  up_invalidate_icache_all();
401	#endif
402	
403	#ifdef CONFIG_ARM_MPU
404	  mpu_control(false, false, false);
405	#endif
406	
407	  /* Set main and process stack pointers, jump to reset handler.
408	   * Use the vector table we read from the image (which points to
409	   * addresses relative to the PSRAM load address).
410	   */
411	
412	  __asm__ __volatile__("\tmsr msp, %0\n"
413	                       "\tmsr control, %1\n"
414	                       "\tisb\n"
415	                       "\tmov pc, %2\n"
416	                       :
417	                       : "r" (vt.spr), "r" (0), "r" (vt.reset));
418	
419	  /* Should never reach here */
420	
421	  return 0;
422	}
