130	static void sifli_psram_preinit(void)
131	{
132	  qspi_configure_t qspi_cfg =
133	  {
134	    .Instance = hwp_qspi1,
135	    .SpiMode  = CONFIG_BSP_QSPI1_MODE,
136	    .msize    = CONFIG_BSP_QSPI1_MEM_SIZE,
137	    .base     = QSPI1_MEM_BASE,
138	  };
139	  static FLASH_HandleTypeDef psram_handle;
140	
141	  /* Enable 1.8V LDO required by PSRAM (may not be available on all chips). */
142	
143	#ifdef PMU_PERI_LDO_1V8
144	  HAL_PMU_ConfigPeriLdo(PMU_PERI_LDO_1V8, true, true);
145	#endif
146	
147	  /* Use SYSCLK for early boot safety. DLL2 path is enabled later by HAL. */
148	
149	  HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_FLASH1, RCC_CLK_FLASH_SYSCLK);
150	
151	  /* Use configured PSRAM mode directly to avoid early-boot PID dependency. */
152	
153	  if (qspi_cfg.SpiMode == SPI_MODE_NOR)
154	    {
155	      g_psram_ready = false;
156	      return;
157	    }
158	
159	  /* Avoid early power-mode query here; HAL_Init will handle PM state later. */
160	
161	  psram_handle.wakeup = 0;
162	
163	  /* Keep divider aligned with existing board implementation. */
164	
165	  g_psram_ready = (HAL_MPI_PSRAM_Init(&psram_handle, &qspi_cfg, 2) == HAL_OK);
166	}
