178	static uint8_t psram_get_default_type(uint32_t mpi_id)
179	{
180	    uint8_t psram_type = SPI_MODE_NOR;
181	#ifdef SOC_SF32LB52X
182	    uint32_t pid = (hwp_hpsys_cfg->IDR & HPSYS_CFG_IDR_PID_Msk) >> HPSYS_CFG_IDR_PID_Pos;
183	    pid &= 7;
184	
185	    switch (pid)
186	    {
187	    case 5: //BOOT_PSRAM_APS_16P:
188	        psram_type = SPI_MODE_PSRAM;         // 16Mb APM QSPI PSRAM
189	        break;
190	    case 4: //BOOT_PSRAM_APS_32P:
191	        psram_type = SPI_MODE_LEGPSRAM;    // 32Mb APM LEGACY PSRAM
192	        break;
193	    case 6: //BOOT_PSRAM_WINBOND:                // Winbond HYPERBUS PSRAM
194	        psram_type = SPI_MODE_HBPSRAM;
195	        break;
196	    case 3: // BOOT_PSRAM_APS_64P:
197	    case 2: //BOOT_PSRAM_APS_128P:
198	        psram_type = SPI_MODE_OPSRAM;      // 64Mb APM XCELLA PSRAM
199	        break;
200	    default:
201	        psram_type = SPI_MODE_NOR;
202	        break;
203	    }
204	#elif defined(SF32LB56X)
205	    uint32_t sip1 = BSP_Get_Sip1_Mode();
206	    uint32_t sip2 = BSP_Get_Sip2_Mode();
207	    if (mpi_id == 1)
208	    {
209	        if (sip1 != 0)  // if chip pass ate, use it to cover local config?
210	        {
211	            switch (sip1)
212	            {
213	            case SFPIN_SIP1_APM_XCA64:
214	                psram_type = SPI_MODE_OPSRAM;
215	                break;
216	            case SFPIN_SIP1_APM_LEG32:
217	                psram_type = SPI_MODE_LEGPSRAM;
218	                break;
219	            case SFPIN_SIP1_WINB_HYP64:
220	            case SFPIN_SIP1_WINB_HYP32:
221	                psram_type = SPI_MODE_HBPSRAM;
222	                break;
223	            default:
224	                psram_type = SPI_MODE_NOR;
225	                break;
226	            }
227	        }
228	        else
229	        {
230	#ifdef PSRAM_BL_MODE
231	            psram_type = PSRAM_BL_MODE;
232	#endif
233	        }
234	    }
235	    else if (mpi_id == 2)
236	    {
237	        if (sip2 != 0)  // if chip pass ate, use it to cover local config?
238	        {
239	            switch (sip2)
240	            {
241	            case SFPIN_SIP2_APM_XCA128:
242	                psram_type = SPI_MODE_OPSRAM;
243	                break;
244	            case SFPIN_SIP2_APM_LEG32:
245	                psram_type = SPI_MODE_LEGPSRAM;
246	                break;
247	            default:
248	                psram_type = SPI_MODE_NOR;
249	                break;
250	            }
251	        }
252	        else
253	        {
254	#ifdef PSRAM_BL_MODE
255	            psram_type = PSRAM_BL_MODE;
256	#endif
257	        }
258	    }
259	#endif
260	
261	    return psram_type;
262	}
