6	 *
7	 * board_boot_image() for SF32LB58 nxboot: loads firmware from NAND to PSRAM
8	 * and jumps to it.  PSRAM must NOT be re-initialized here — the application
9	 * code and data have already been copied from NAND to PSRAM by the time
10	 * this function runs.
11	 ****************************************************************************/
12	
13	/****************************************************************************
14	 * Included Files
15	 ****************************************************************************/
16	
17	#include <nuttx/config.h>
18	
19	#include <debug.h>
20	#include <stdio.h>
21	#include <fcntl.h>
22	#include <string.h>
