27	#include <arch/barriers.h>
28	
29	#include "nvic.h"
30	#include "arm_internal.h"
31	
32	/****************************************************************************
33	 * Pre-processor Definitions
34	 ****************************************************************************/
35	
36	/* Application load address in PSRAM.
37	 * Must match the application's linker script origin.
38	 * PSRAM starts at 0x60000000; first 4MB reserved for SDK regions;
39	 * application code goes at 0x60400000.
40	 */
41	
42	#define SF32LB58_APP_PSRAM_LOAD_ADDR  0x60400000
43	
44	/* Maximum image size we can load (12 MB, leaving room for heap) */
45	
46	#define SF32LB58_APP_MAX_IMAGE_SIZE   (12U * 1024U * 1024U)
47	
48	/* Read buffer size for NAND→PSRAM copy */
49	
50	#define SF32LB58_COPY_BUF_SIZE        4096
51	
52	/****************************************************************************
53	 * Private Types
54	 ****************************************************************************/
55	
56	/* ARM vector table: first two words of a Cortex-M image */
57	
58	struct arm_vector_table
59	{
60	  uint32_t spr;   /* Stack pointer on reset */
61	  uint32_t reset; /* Pointer to reset exception handler */
62	};
63	
64	/****************************************************************************
65	 * Private Functions
66	 ****************************************************************************/
67	
68	/****************************************************************************
69	 * Name: cleanup_arm_nvic
70	 *
71	 * Description:
72	 *   Acknowledge and disable all interrupts in NVIC.
73	 *
74	 ****************************************************************************/
75	
76	static void cleanup_arm_nvic(void)
77	{
78	  int i;
79	
80	  UP_ISB();
81	  up_irq_disable();
82	
83	  for (i = 0; i < NR_IRQS; i += 32)
84	    {
85	      putreg32(0xffffffff, NVIC_IRQ_CLEAR(i));
86	    }
87	
88	  for (i = 0; i < NR_IRQS; i += 32)
89	    {
90	      putreg32(0xffffffff, NVIC_IRQ_CLRPEND(i));
91	    }
92	}
93	
94	/****************************************************************************
95	 * Name: systick_disable
96	 *
97	 * Description:
98	 *   Disable the SysTick system timer.
99	 *
100	 ****************************************************************************/
101	
102	static void systick_disable(void)
103	{
104	  putreg32(0, NVIC_SYSTICK_CTRL);
105	  putreg32(NVIC_SYSTICK_RELOAD_MASK, NVIC_SYSTICK_RELOAD);
106	  putreg32(0, NVIC_SYSTICK_CURRENT);
107	}
