    volatile uint32_t *psram = (volatile uint32_t *)dest;
    uint32_t r0 = psram[0];
    uint32_t r1 = psram[1];
    uint32_t r2 = psram[2];
    uint32_t r3 = psram[3];
    uint32_t s0 = ((uint32_t *)buf)[0];
    uint32_t s1 = ((uint32_t *)buf)[1];
    uint32_t s2 = ((uint32_t *)buf)[2];
    uint32_t s3 = ((uint32_t *)buf)[3];

    syslog(LOG_INFO,
           "PSRAM readback: %08lx %08lx %08lx %08lx\n",
           (unsigned long)r0, (unsigned long)r1,
           (unsigned long)r2, (unsigned long)r3);
    syslog(LOG_INFO,
           "SRAM  source:   %08lx %08lx %08lx %08lx\n",
           (unsigned long)s0, (unsigned long)s1,
           (unsigned long)s2, (unsigned long)s3);

    /* Dump QSPI1 (MPI1) controller registers.
     * Base = 0x40081000
     *   CR    +0x00  (control)
     *   SR    +0x10  (status)
     *   HCMDR +0x40  (AHB read/write opcodes)
     *   HRCCR +0x48  (AHB read cmd format)
     *   HWCCR +0x50  (AHB write cmd format)
     */

    volatile uint32_t *qspi1 = (volatile uint32_t *)0x40081000;
    uint32_t cr    = qspi1[0x00 / 4];
    uint32_t sr    = qspi1[0x10 / 4];
    uint32_t hcmdr = qspi1[0x40 / 4];
    uint32_t hrccr = qspi1[0x48 / 4];
    uint32_t hwccr = qspi1[0x50 / 4];

    syslog(LOG_INFO,
           "QSPI1 CR=%08lx SR=%08lx HCMDR=%08lx HRCCR=%08lx "
           "HWCCR=%08lx\n",
           (unsigned long)cr, (unsigned long)sr,
