    HAL_FLASH_CFG_AHB_RCMD(handle, 3, 6, 0, 0, 2, 3, 1);
    res = HAL_FLASH_SET_AHB_RCMD(handle, HAL_QPSRAM_QRD);

    /* enable quadline write.
     * At 144 MHz the PSRAM needs write latency (dummy cycles)
     * between the address and data phases.  Without it, writes
     * produce corrupted data and burst writes beyond the first
     * word have no effect.  DCYC=3 matches the typical QSPI
     * PSRAM write latency at this frequency.
     */

    HAL_FLASH_CFG_AHB_WCMD(handle, 3, 3, 0, 0, 2, 3, 1);
    res = HAL_FLASH_SET_AHB_WCMD(handle, HAL_QPSRAM_QWR);
}

