222	static int boot_nand_init()
223	{
224	    qspi_configure_t flash_cfg; // = FLASH3_CONFIG;
225	    struct dma_config flash_dma;
226	    uint16_t div;
227	    HAL_StatusTypeDef res = HAL_ERROR;
228	    int clk_mode;
229	    memset(&spi_nand_handle, 0, sizeof(QSPI_FLASH_CTX_T));
230	
231	#if defined(BSP_ENABLE_QSPI3) && (BSP_QSPI3_MODE == SPI_MODE_NAND)
232	    qspi_configure_t flash_cfg3 = FLASH3_CONFIG;
233	    struct dma_config flash_dma3 = FLASH3_DMA_CONFIG;
234	
235	    // set clock divider, it related with source clock freq
236	    div = BSP_GetFlash3DIV();
237	    clk_mode = RCC_CLK_MOD_FLASH3;
238	    memcpy(&flash_cfg, &flash_cfg3, sizeof(qspi_configure_t));
239	    memcpy(&flash_dma, &flash_dma3, sizeof(struct dma_config));
240	#elif defined(BSP_ENABLE_QSPI4) && (BSP_QSPI4_MODE == SPI_MODE_NAND)
241	    qspi_configure_t flash_cfg4 = FLASH4_CONFIG;
242	    struct dma_config flash_dma4 = FLASH4_DMA_CONFIG;
243	
244	    // set clock divider, it related with source clock freq
245	    div = BSP_GetFlash4DIV();
246	    clk_mode = RCC_CLK_MOD_FLASH4;
247	    memcpy(&flash_cfg, &flash_cfg4, sizeof(qspi_configure_t));
248	    memcpy(&flash_dma, &flash_dma4, sizeof(struct dma_config));
249	#elif defined(BSP_ENABLE_QSPI2) && (BSP_QSPI2_MODE == SPI_MODE_NAND)
250	    qspi_configure_t flash_cfg2 = FLASH2_CONFIG;
251	    struct dma_config flash_dma2 = FLASH2_DMA_CONFIG;
252	
253	    // set clock divider, it related with source clock freq
254	    div = BSP_GetFlash2DIV();
255	    clk_mode = RCC_CLK_MOD_FLASH2;
256	    memcpy(&flash_cfg, &flash_cfg2, sizeof(qspi_configure_t));
257	    memcpy(&flash_dma, &flash_dma2, sizeof(struct dma_config));
258	#endif
259	
260	    // for nand, use nand interface to read/write, do not use AHB, so do not care address
261	    if (flash_cfg.SpiMode == SPI_MODE_NAND)
262	    {
263	#ifdef SOC_SF32LB55X
264	        if (flash_cfg.msize > (QSPI3_MAX_SIZE >> 20))
265	            flash_cfg.msize = QSPI3_MAX_SIZE >> 20;
266	#else
267	        flash_cfg.base = HCPU_MPI_SBUS_ADDR(flash_cfg.base);
268	#endif
269	    }
270	    else
271	    {
272	        return 0;
273	    }
274	
275	    spi_nand_handle.handle.freq = flash_get_freq(clk_mode, div, 1);
276	    // init hardware, set dma, clock
277	    res = HAL_FLASH_Init(&spi_nand_handle, &flash_cfg, &spi_nand_dma_handle, &flash_dma, div);
278	    if (res == HAL_OK)
279	    {
280	        nand_pagesize = HAL_NAND_PAGE_SIZE(&spi_nand_handle.handle);
281	        nand_blksize = HAL_NAND_BLOCK_SIZE(&spi_nand_handle.handle);
282	
283	        spi_nand_handle.handle.data_buf = (uint8_t *)nand_cache;
284	        spi_nand_handle.handle.buf_mode = 1;    // default set to buffer mode for nand
285	        HAL_NAND_CONF_ECC(&spi_nand_handle.handle, 1); // default enable ECC if support !
286	        bbm_set_page_size(nand_pagesize);
287	        bbm_set_blk_size(nand_blksize);
288	        sif_bbm_init(spi_nand_handle.total_size, (uint8_t *)bbm_cache_buf);
289	
290	        return 1;
291	    }
292	
293	    return 0;
294	}
