296	int port_read_page(int blk, int page, int offset, uint8_t *buff, uint32_t size, uint8_t *spare, uint32_t spare_len)
297	{
298	    int res;
299	    uint32_t addr = (blk * nand_blksize) + (page * nand_pagesize) + offset;
300	
301	    FLASH_HandleTypeDef *hflash = (FLASH_HandleTypeDef *)&spi_nand_handle.handle;
302	    if ((offset + size) > nand_pagesize)
303	    {
304	        HAL_ASSERT(0);
305	    }
306	#if (NAND_BUF_CPY_MODE == 1)
307	    SCB_InvalidateDCache_by_Addr(buff, size);
308	#endif
309	    SCB_InvalidateDCache_by_Addr((void *)hflash->base, nand_pagesize + SPI_NAND_MAXOOB_SIZE);
310	    if (((blk & 1) != 0) && (hflash->wakeup != 0))
311	        SCB_InvalidateDCache_by_Addr((void *)(hflash->base + (1 << 12)), SPI_NAND_PAGE_SIZE + SPI_NAND_MAXOOB_SIZE);
312	    res = HAL_NAND_READ_WITHOOB(hflash, addr, buff, size, spare, spare_len);
313	
314	
315	    return res; //RET_NOERROR;
316	}
