496	__HAL_ROM_USED HAL_StatusTypeDef HAL_MPI_SET_FIXLAT(FLASH_HandleTypeDef *hflash, uint32_t fix, uint8_t r_lat, uint8_t w_lat)
497	{
498	    uint8_t val, val4;
499	    if (hflash == NULL)
500	        return HAL_ERROR;
501	
502	    uint8_t rlat_arr[8] = {0, 0, 0, 0, 1, 2, 3, 4};
503	    uint8_t wlat_arr[8] = {0, 0, 0, 0, 4, 2, 6, 1};
504	
505	    HAL_MPI_EN_FIXLAT(hflash, fix);
506	
507	    // MR0[7:6] fix 0, [5] Latency type, [4:2] Read latency code, [1:0] drive str
508	    // MR4[7:5] Write latency code, [4:3] RF rate, [2:0] PASR
509	    if (fix)
510	    {
511	        val = (1 << 5) | (rlat_arr[r_lat / 2] << 2) | 1;
512	        val4 = ((wlat_arr[w_lat]) << 5) | (0 << 3) | 0;
513	    }
514	    else
515	    {
516	        val = (0 << 5) | (rlat_arr[r_lat] << 2) | 1;
517	        val4 = ((wlat_arr[w_lat]) << 5) | (0 << 3) | 0;
518	    }
519	
520	    HAL_MPI_MR_WRITE(hflash, 0, val);
521	    HAL_MPI_MODIFY_RCMD_DELAY(hflash, r_lat - 1); // NOTE  , as digital suggest, 10 to 9,
522	
523	    HAL_MPI_MR_WRITE(hflash, 4, val4);
524	    HAL_MPI_MODIFY_WCMD_DELAY(hflash, w_lat - 1); // NOTE  , as digital suggest, 10 to 9,
525	    return HAL_OK;
526	}
