161	#endif /* CONFIG_BSP_USING_PSRAM2 */
162	    };
163	
164	    idx = 0;
165	
166	#ifdef CONFIG_BSP_USING_PSRAM1
167	    psram_clk_div[idx] = BSP_GetFlash1DIV();
168	    idx++;
169	#endif /* CONFIG_BSP_USING_PSRAM1 */
170	#ifdef CONFIG_BSP_USING_PSRAM2
171	    psram_clk_div[idx] = BSP_GetFlash2DIV();
172	    idx++;
173	#endif /* CONFIG_BSP_USING_PSRAM2 */
174	
175	    psram_num = sizeof(bf0_psram_cfg) / sizeof(bf0_psram_cfg[0]);
176	
177	#ifdef SOC_SF32LB56X
178	    /* extend MPI1 space to 64Mb for 56x if psram supported */
179	    hwp_hpsys_cfg->SYSCR |= HPSYS_CFG_SYSCR_REMAP;
180	#endif
181	
182	    /* init as 0 in case reach here before bss is initialized */
183	    flash_memset(&bf0_psram_handle[0], 0, sizeof(bf0_psram_handle));
184	    for (i = 0; i < psram_num; i++)
185	    {
186	        if (bf0_psram_cfg[i].is_qspi)
187	        {
188	            FLASH_HandleTypeDef *handle;
189	            qspi_configure_t qspi_cfg;
190	
191	            flash_memset(&qspi_cfg, 0, sizeof(qspi_configure_t));
192	
193	            handle = &bf0_psram_handle[i].qspi_handle;
194	
195	            qspi_cfg.Instance = (MPI_TypeDef *)bf0_psram_cfg[i].instance;
196	
197	            /* Match SDK: always use SPI_MODE_PSRAM (quad-line QSPI PSRAM)
198	             * for the QSPI path, regardless of CONFIG_BSP_QSPI1_MODE.
199	             * The is_qspi field is only used as a boolean to select the

195	            qspi_cfg.Instance = (MPI_TypeDef *)bf0_psram_cfg[i].instance;
196	
197	            /* Match SDK: always use SPI_MODE_PSRAM (quad-line QSPI PSRAM)
198	             * for the QSPI path, regardless of CONFIG_BSP_QSPI1_MODE.
199	             * The is_qspi field is only used as a boolean to select the
200	             * QSPI vs PSRAMC path.
201	             */
202	            qspi_cfg.SpiMode = SPI_MODE_PSRAM;
203	
204	            qspi_cfg.msize = bf0_psram_cfg[i].msize;
205	            qspi_cfg.base = bf0_psram_cfg[i].base_addr;
206	            if (PM_STANDBY_BOOT == SystemPowerOnModeGet())
207	                handle->wakeup = 1;
208	            else
209	                handle->wakeup = 0;
210	
211	            res = HAL_SPI_PSRAM_Init(handle, &qspi_cfg, psram_clk_div[i]);
212	            g_psram_ready = (res == HAL_OK);
213	
214	            if (res != HAL_OK)
215	                continue;
216	
217	            /* Configure AHB read/write commands for quadline QSPI PSRAM.
218	             * Match SDK's bsp_psramc_init() exactly.
219	             */
220	
221	            /* enable quadline read:
222	             *   IMODE=3(quad), DCYC=6, ADMODE=0, ADSIZE=0,
223	             *   ABMODE=2, ABSIZE=3, DMODE=1
224	             * read command: BF0_QPSRAM_QRD (0xEB)
225	             */
226	            HAL_FLASH_CFG_AHB_RCMD(handle, 3, 6, 0, 0, 2, 3, 1);
227	            res = HAL_FLASH_SET_AHB_RCMD(handle, HAL_QPSRAM_QRD);
228	
229	            /* enable quadline write:
230	             *   IMODE=3(quad), DCYC=0, ADMODE=0, ADSIZE=0,
231	             *   ABMODE=2, ABSIZE=3, DMODE=1
232	             * write command: HAL_QPSRAM_QWR (0x38)
233	             */
234	            HAL_FLASH_CFG_AHB_WCMD(handle, 3, 0, 0, 0, 2, 3, 1);
235	            res = HAL_FLASH_SET_AHB_WCMD(handle, HAL_QPSRAM_QWR);
236	
237	            /* Write test for diagnostics.
238	             * Store at 0x20001F00 for JLink inspection.
239	             */
240	            if (qspi_cfg.Instance == hwp_qspi1)
241	            {
242	                volatile uint32_t *dbg = (volatile uint32_t *)0x20001F00;
243	                volatile uint32_t *qspi1 = (volatile uint32_t *)0x40081000;
244	                dbg[0] = (uint32_t)res;  /* AHB cmd setup result */
245	                dbg[1] = qspi1[0x00 / 4];  /* CR */
246	                dbg[2] = qspi1[0x40 / 4];  /* HCMDR */
247	                dbg[3] = qspi1[0x48 / 4];  /* HRCCR */
248	                dbg[4] = qspi1[0x50 / 4];  /* HWCCR */
249	                int psram_id = HAL_QSPI_GET_PSRAM_ID(handle);
250	                dbg[5] = psram_id;
251	                /* Write test */
252	                volatile uint32_t *psram = (volatile uint32_t *)0x60400000;
253	                psram[0] = 0xDEADBEEF;
254	                psram[1] = 0xCAFEBABE;
255	                psram[2] = 0x12345678;
256	                psram[3] = 0xAABBCCDD;
257	                dbg[6] = psram[0];
258	                dbg[7] = psram[1];
259	                dbg[8] = psram[2];
260	                dbg[9] = psram[3];
261	            }
262	        }
263	    }
264	    return res;
265	}
