#ifdef SOC_BF0_HCPU
    /* PSRAM pinmux — must match chip variant.
     * 583: DIO0-3 on SA04-07, CS=SA09, CLK=SA10, DIO4-7=SA11-14, DQS0=SA15
     * 585/587: DIO0-7 on SA00-07, DQS0=SA08, CLK=SA09, CS=SA10, DIO8-15=SA11-19
     */
    if (CHIP_IS_583())
    {
        /* 583: 8-bit OPI PSRAM on SA04-SA15 */
        HAL_PIN_Set(PAD_SA04, MPI1_DIO0, PIN_PULLDOWN, 1);
        HAL_PIN_Set(PAD_SA05, MPI1_DIO1, PIN_PULLDOWN, 1);
