/**
 * @brief  PSRAM controller hardware initial.
 *
 * The ROM bootloader initializes the PSRAM controller (MPI1) before our code
 * runs, including pin mux, clock, and SPI mode (OPI per CONFIG_BSP_MPI1_MODE_3).
 * The SDK also skips PSRAM reinit in HAL_PreInit() — sifli_psram_preinit() and
 * bsp_psramc_init() are both commented out.
 *
 * We just verify PSRAM is accessible by doing a read/write test at 0x60000000.
 */
int bsp_psramc_init(void)
{
    volatile uint32_t *psram = (volatile uint32_t *)PSRAM_START;
    uint32_t save0, save1;

    /* Save original content */
    save0 = psram[0];
    save1 = psram[1];

    /* Write test pattern */
    psram[0] = 0xDEADBEEF;
    psram[1] = 0xCAFEBABE;

    /* Verify */
    if (psram[0] == 0xDEADBEEF && psram[1] == 0xCAFEBABE)
    {
        g_psram_ready = true;
        /* Restore original content */
        psram[0] = save0;
        psram[1] = save1;
        return 0;
    }

    /* Restore original content even on failure */
    psram[0] = save0;
    psram[1] = save1;
    g_psram_ready = false;
    return -1;
}

